/**
 * Build-time configuration for self-hosted live updates (docs/TRELLISKIT.md section 8.1). Node
 * only: app.config.js and the update scripts use it; app code never does.
 *
 * The app uses expo-updates against TrellisKit's own Expo Updates protocol v1 endpoint,
 * GET /api/v1/updates/manifest on the property's API domain. Code signing is mandatory: the
 * property's certificate lives at <property>/mobile/updates/certificate.pem (generated by
 * scripts/generate-updates-certificate.js; the private key is never in the repository). Without
 * a certificate the build has updates disabled and prints a warning.
 *
 * Environment:
 * - TK_UPDATES_URL: full manifest URL override (for example a local Docker backend,
 *   http://127.0.0.1:8000/api/v1/updates/manifest).
 * - EXPO_PUBLIC_API_URL: when set (and TK_UPDATES_URL is not), the manifest URL is built from it,
 *   so a build pointed at a local backend also checks that backend for updates.
 * - TK_UPDATES_CHANNEL: channel override (production, preview, or development). Otherwise it
 *   follows APP_VARIANT from the EAS build profile; anything else is development.
 * - TK_UPDATES_DISABLED=1: build without updates even when the certificate exists.
 *
 * Channels (docs/LIVE_UPDATES_CONTRACT.md decision 15): the channel is NOT native configuration.
 * The native request headers are identical for every channel (`expo-channel-name` carries the
 * placeholder EmbeddedChannel, `X-TK-Install-Id` is empty), so preview and production binaries of
 * one commit have the same fingerprint (runtime version). The build channel goes only to
 * `extra.updates.channel`, which fingerprint.config.js skips, and the app sets the real header
 * values at runtime with Updates.setUpdateRequestHeadersOverride (src/updates/requestHeaders.js).
 * expo-updates only accepts override keys that exist in the embedded headers, which is why every
 * runtime header has an embedded placeholder.
 *
 * Key rotation (decision 14): certificate.pem (key id `main`) is embedded and is a CA;
 * standby-certificate.pem (key id `standby`) is issued by it. The build turns on
 * expo-updates' manifest response certificate chain option (plugins/withUpdatesCertificateChain.js)
 * so manifests signed by the standby key, sent with standby-certificate.pem as the chain, are
 * accepted without a new binary. See scripts/updatesCertificates.js.
 */
const fs = require('fs');
const path = require('path');
const { propertySlug } = require('./property');

/** Manifest route on the property's API domain. */
const ManifestPath = '/api/v1/updates/manifest';

/** Certificate location inside a property folder. */
const CertificateRelativePath = path.join('mobile', 'updates', 'certificate.pem');

/** Standby certificate location inside a property folder. */
const StandbyCertificateRelativePath = path.join('mobile', 'updates', 'standby-certificate.pem');

/** Optional key id file inside a property folder ({ activeKeyId, standbyKeyId }). */
const SigningConfigRelativePath = path.join('mobile', 'updates', 'signing.json');

/** Key ids until a promotion writes signing.json. */
const DefaultKeyIds = Object.freeze({ activeKeyId: 'main', standbyKeyId: 'standby' });

/** Code signing metadata the backend signs with (expo-signature keyid and alg) for the default key ids. */
const CodeSigningMetadata = Object.freeze({ keyid: DefaultKeyIds.activeKeyId, alg: 'rsa-v1_5-sha256' });

/**
 * Embedded value of the expo-channel-name header. The app replaces it at runtime before its first
 * check; only a native crash recovery check on the very first launch can send it.
 */
const EmbeddedChannel = 'production';

/** Runtime update request headers (each needs an embedded placeholder for the override to be accepted). */
const RuntimeHeaders = Object.freeze({ channel: 'expo-channel-name', installId: 'X-TK-Install-Id' });

/** Channels a build can be on. */
const Channels = Object.freeze(['production', 'preview', 'development']);

/** Default minimum minutes between update checks (property setting updates.checkIntervalMinutes). */
const DefaultCheckIntervalMinutes = 15;

function read(env, name) {
  return ((env && env[name]) || '').trim();
}

/**
 * The update channel for a build.
 * @param {Record<string, string|undefined>} env
 * @returns {string}
 */
function resolveChannel(env = process.env) {
  const explicit = read(env, 'TK_UPDATES_CHANNEL').toLowerCase();
  if (explicit) {
    if (!Channels.includes(explicit)) throw new Error('TK_UPDATES_CHANNEL must be one of ' + Channels.join(', ') + ' (got ' + explicit + ').');
    return explicit;
  }
  const variant = read(env, 'APP_VARIANT').toLowerCase();
  return variant === 'production' || variant === 'preview' ? variant : 'development';
}

/**
 * The manifest URL for a build, or '' when it cannot be determined.
 * @param {object} property
 * @param {Record<string, string|undefined>} env
 * @returns {string}
 */
function resolveUpdatesUrl(property, env = process.env) {
  const override = read(env, 'TK_UPDATES_URL');
  if (override) return override;
  const apiUrl = read(env, 'EXPO_PUBLIC_API_URL').replace(/\/+$/, '');
  if (apiUrl) return apiUrl + ManifestPath;
  const domain = property && property.domains && typeof property.domains.api === 'string' ? property.domains.api.trim() : '';
  return domain ? 'https://' + domain + ManifestPath : '';
}

/**
 * Absolute path of a property's code signing certificate.
 * @param {string} propertyDir Absolute property directory.
 */
function certificatePath(propertyDir) {
  return path.join(propertyDir, CertificateRelativePath);
}

/** Absolute path of a property's standby certificate. */
function standbyCertificatePath(propertyDir) {
  return path.join(propertyDir, StandbyCertificateRelativePath);
}

/** Absolute path of a property's optional signing.json. */
function signingConfigPath(propertyDir) {
  return path.join(propertyDir, SigningConfigRelativePath);
}

/**
 * The property's key ids (signing.json, else main and standby).
 * @param {string} propertyDir
 * @returns {{ activeKeyId: string, standbyKeyId: string }}
 */
function readSigningConfig(propertyDir) {
  const file = signingConfigPath(propertyDir);
  if (!fs.existsSync(file)) return { ...DefaultKeyIds };
  const value = JSON.parse(fs.readFileSync(file, 'utf8'));
  const valid = (id) => typeof id === 'string' && /^[A-Za-z0-9._-]{1,64}$/.test(id);
  if (!valid(value.activeKeyId) || !valid(value.standbyKeyId) || value.activeKeyId === value.standbyKeyId) throw new Error(file + ' must have two different key ids, activeKeyId and standbyKeyId.');
  return { activeKeyId: value.activeKeyId, standbyKeyId: value.standbyKeyId };
}

/**
 * Inspect the property's certificates for key rotation.
 * @returns {{ keyIds: object, includeCertificateChain: boolean, standby: boolean, warning: string|null }}
 */
function signingConfig(propertyDir) {
  const { inspectCertificates } = require('./updatesCertificates');
  const keyIds = readSigningConfig(propertyDir);
  const standbyFile = standbyCertificatePath(propertyDir);
  const standbyPem = fs.existsSync(standbyFile) ? fs.readFileSync(standbyFile, 'utf8') : null;
  const report = inspectCertificates({ activePem: fs.readFileSync(certificatePath(propertyDir), 'utf8'), standbyPem });
  const fix = 'Run: node scripts/generate-updates-certificate.js ' + propertyDir;
  let warning = null;
  if (!report.activeIsCa) warning = 'certificate.pem is not a CA certificate, so builds cannot accept the standby key and key rotation needs a new binary. ' + fix + ' --reissue-active --standby --active-key <the active private key>';
  else if (!standbyPem) warning = 'no standby certificate at ' + standbyFile + ', so the server has no standby key to rotate to. ' + fix + ' --standby --active-key <the active private key>';
  else if (report.problems.length) warning = 'key rotation is not ready: ' + report.problems.join('; ') + '.';
  // The chain option is harmless without a standby: a manifest without a certificate_chain part is
  // verified against the embedded certificate alone. It needs a CA certificate to accept chains.
  return { keyIds, includeCertificateChain: report.activeIsCa, standby: report.rotationReady, warning };
}

/**
 * The expo-updates part of the app config for a property.
 * @param {object} options
 * @param {object} options.property Parsed property.json.
 * @param {string} options.propertyDir Absolute property directory.
 * @param {string} options.projectRoot Absolute mobile/ directory (the certificate path is relative to it).
 * @param {Record<string, string|undefined>} [options.env]
 * @returns {{ enabled: boolean, warning: string|null, rotationWarning: string|null, includeCertificateChain: boolean, channel: string, url: string, updates: object, runtimeVersion: object, requestHeaders: object|null, extra: object }}
 */
function updatesConfig({ property, propertyDir, projectRoot, env = process.env }) {
  const channel = resolveChannel(env);
  const url = resolveUpdatesUrl(property, env);
  const certificate = certificatePath(propertyDir);
  const hasCertificate = fs.existsSync(certificate);
  const runtimeVersion = { policy: 'fingerprint' };
  const settings = (property && property.updates) || {};
  const interval = Number(settings.checkIntervalMinutes);
  const extra = {
    channel,
    checkIntervalMinutes: Number.isFinite(interval) && interval > 0 ? interval : DefaultCheckIntervalMinutes
  };

  let warning = null;
  if (read(env, 'TK_UPDATES_DISABLED') === '1') warning = 'Live updates are disabled by TK_UPDATES_DISABLED=1.';
  else if (!hasCertificate) warning = 'Live updates are disabled for property "' + propertySlug(property) + '": no code signing certificate at ' + certificate + '. Run: node scripts/generate-updates-certificate.js ' + propertyDir;
  else if (!url) warning = 'Live updates are disabled for property "' + propertySlug(property) + '": no domains.api and no TK_UPDATES_URL.';

  if (warning) {
    return { enabled: false, warning, rotationWarning: null, includeCertificateChain: false, channel, url, runtimeVersion, requestHeaders: null, updates: { enabled: false }, extra: { ...extra, enabled: false } };
  }

  const signing = signingConfig(propertyDir);
  // One header map serves both platforms and every channel; X-TK-App is set per platform by
  // plugins/withUpdatesAppHeader.js (iOS bundle id, Android package). The channel and the install
  // id are placeholders replaced at runtime (see the header comment).
  const requestHeaders = {
    [RuntimeHeaders.channel]: EmbeddedChannel,
    'X-TK-Property': property.id,
    'X-TK-App': property.mobile.bundleId,
    [RuntimeHeaders.installId]: ''
  };
  const updates = {
    enabled: true,
    url,
    // The app-level controller (src/updates/) checks on launch and on foreground; native checks
    // only while recovering from a crash.
    checkAutomatically: 'ON_ERROR_RECOVERY',
    fallbackToCacheTimeout: 0,
    codeSigningCertificate: path.relative(projectRoot, certificate).split(path.sep).join('/'),
    codeSigningMetadata: { ...CodeSigningMetadata, keyid: signing.keyIds.activeKeyId },
    requestHeaders
  };
  return {
    enabled: true,
    warning: null,
    rotationWarning: signing.warning,
    includeCertificateChain: signing.includeCertificateChain,
    channel,
    url,
    runtimeVersion,
    requestHeaders,
    updates,
    extra: { ...extra, enabled: true, url }
  };
}

module.exports = {
  ManifestPath,
  CertificateRelativePath,
  StandbyCertificateRelativePath,
  SigningConfigRelativePath,
  DefaultKeyIds,
  CodeSigningMetadata,
  EmbeddedChannel,
  RuntimeHeaders,
  Channels,
  DefaultCheckIntervalMinutes,
  resolveChannel,
  resolveUpdatesUrl,
  certificatePath,
  standbyCertificatePath,
  signingConfigPath,
  readSigningConfig,
  signingConfig,
  updatesConfig
};
